try:
    if not isinstance(sql, str):
        raise ValueError("The 'sql' parameter must be a string.")

    result = sqlglot.transpile(
        sql=sql,
        read=read_dialect,
        write=write_dialect,
        identity=identity,
        error_level=error_level
    )

    success = True
    display_summary = f"Transpiled {len(result)} statements from {read_dialect or 'standard'} to {write_dialect or 'standard'}"

    return {
        "transpiled_statements": result,
        "success": success,
        "display_summary": display_summary
    }
except Exception as e:
    return {
        "transpiled_statements": [],
        "success": False,
        "display_summary": f"Transpilation failed: {str(e)}"
    }
